input.sparql:
PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/ref#>
SELECT DISTINCT ?point ?tsid ?pcl WHERE {
  ?point brick:hasProperty <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F1_Z02> .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
  OPTIONAL { ?point brick:instanceOf ?pcl . }
}

